<?php $subtotal=0;foreach($cartItems as $item){$subtotal+=$item['price']*$item['quantity'];} ?>
<section class="yv-checkout-hero"><div class="container"><div class="breadcrumb"><a href="/">Ana Sayfa</a> / <a href="/sepet">Sepet</a> / Ödeme</div><h1><span>Güvenli Ödeme</span> ile siparişinizi tamamlayın.</h1><p>Ödeme yönteminizi seçin, gerekli hizmet bilgilerini girin ve siparişinizi güvenle oluşturun.</p><div class="yv-steps"><div class="yv-step active"><span><?= icon('shopping-cart',14) ?></span><strong>1 · Sepet</strong><small>Tamamlandı</small></div><div class="yv-step active"><span><?= icon('credit-card',14) ?></span><strong>2 · Ödeme</strong><small>Bilgileri tamamla</small></div><div class="yv-step"><span><?= icon('check',14) ?></span><strong>3 · Onay</strong><small>Siparişi oluştur</small></div></div></div></section>
<section class="yv-checkout-page"><div class="container"><form id="checkoutForm" method="POST" action="/odeme/islem"><?= csrfField() ?><div class="yv-commerce-layout">
 <div class="yv-checkout-main">
  <div class="yv-check-card"><div class="yv-check-title"><span>1</span><h2>Müşteri Bilgileri</h2></div><div class="yv-user-box"><div class="yv-user-avatar"><?= e(mb_strtoupper(mb_substr($user['name']??'U',0,1))) ?></div><div><strong><?= e($user['name']??'') ?></strong><small><?= e($user['email']??'') ?></small></div><span class="badge badge-success" style="margin-left:auto">Giriş yapıldı</span></div></div>
  <div class="yv-check-card"><div class="yv-check-title"><span>2</span><h2>Hizmet Bilgileri</h2></div><?php foreach($cartItems as $item): ?><div class="yv-service-item"><div class="yv-service-top"><div><h3><?= e($item['name']) ?></h3><small style="font-size:7px;color:#8a93a6"><?= (int)$item['quantity'] ?> adet</small></div><b><?= money($item['line_total']) ?></b></div><?php if(!empty($item['fields'])): ?><div class="yv-dynamic-fields"><?php foreach($item['fields'] as $field): ?><div class="yv-form-group"><label><?= e($field['field_label']) ?><?= $field['is_required']?' *':'' ?></label><?php if($field['field_type']==='textarea'): ?><textarea class="form-control" name="field_<?= $item['id'] ?>_<?= e($field['field_key']) ?>" rows="2" placeholder="<?= e($field['placeholder']??'') ?>" <?= $field['is_required']?'required':'' ?>></textarea><?php elseif($field['field_type']==='select'): ?><select class="form-control" name="field_<?= $item['id'] ?>_<?= e($field['field_key']) ?>" <?= $field['is_required']?'required':'' ?>><option value="">Seçiniz</option><?php foreach(explode(',',$field['options']??'') as $opt): if(trim($opt)!==''): ?><option value="<?= e(trim($opt)) ?>"><?= e(trim($opt)) ?></option><?php endif; endforeach; ?></select><?php else: ?><input class="form-control" type="<?= $field['field_type']==='url'?'url':'text' ?>" name="field_<?= $item['id'] ?>_<?= e($field['field_key']) ?>" placeholder="<?= e($field['placeholder']??'') ?>" <?= $field['is_required']?'required':'' ?>><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?></div><?php endforeach; ?></div>
 </div>
 <aside class="yv-commerce-card yv-summary"><h3><?= icon('shield',15) ?> Ödeme ve Sipariş Özeti</h3><?php if(empty($paymentOptions)): ?><div class="alert alert-warning">Aktif ödeme yöntemi bulunamadı.</div><?php else: ?><?php foreach($paymentOptions as $i=>$opt): ?><label class="yv-payment-option"><input type="radio" name="payment_gateway" value="<?= e($opt['key']) ?>" <?= ($opt['is_default']||$i===0)?'checked':'' ?> required><div><strong><?= e($opt['name']) ?></strong><small><?= $opt['key']==='bank_transfer'?'Havale/EFT ile güvenli manuel ödeme.':'Kredi veya banka kartı ile güvenli online ödeme altyapısına yönlendirilirsiniz.' ?></small></div></label><?php endforeach; ?><?php endif; ?><div class="yv-form-group" style="margin-top:14px"><label>Sipariş notu (opsiyonel)</label><textarea class="form-control" name="customer_note" rows="2" placeholder="Eklemek istediğiniz not..."></textarea></div><div class="yv-summary-row"><span>Ara toplam</span><b><?= money($subtotal) ?></b></div><?php if($total<$subtotal): ?><div class="yv-summary-row" style="color:#e84b79"><span>İndirim</span><b>-<?= money($subtotal-$total) ?></b></div><?php endif; ?><div class="yv-summary-total"><span>Ödenecek</span><strong><?= money($total) ?></strong></div><label style="display:flex;gap:7px;margin-top:14px;font-size:8px;color:#6f7990"><input type="checkbox" required><span>Mesafeli Satış Sözleşmesi ve Gizlilik Politikası'nı okudum, kabul ediyorum.</span></label><button id="btnCheckoutSubmit" class="yv-summary-cta" style="width:100%;border:0" type="submit"><?= icon('lock',13) ?> Siparişi Onayla ve Öde</button><div class="yv-secure-list"><div><?= icon('shield',13) ?> Ödeme bilgileri güvenli altyapıda işlenir</div><div><?= icon('headphones',13) ?> Satış sonrası destek</div></div></aside>
</div></form></div></section>
<script>document.getElementById('checkoutForm').addEventListener('submit',function(){if(!this.checkValidity())return;const b=document.getElementById('btnCheckoutSubmit');b.disabled=true;b.textContent='Lütfen bekleyin...'});</script>